import numpy as np

def rank_gf2(matrix):
    m, n = matrix.shape
    rank = 0
    for col in range(n):
        if rank >= m: break
        pivot = -1
        for row in range(rank, m):
            if matrix[row][col] == 1:
                pivot = row
                break
        if pivot != -1:
            matrix[rank], matrix[pivot] = matrix[pivot].copy(), matrix[rank].copy()
            for row in range(m):
                if row != rank and matrix[row][col] == 1:
                    matrix[row] = (matrix[row] + matrix[rank]) % 2
            rank += 1
    return rank

def check(n):
    num_cells = n * n
    trominoes = []
    for i in range(n - 1):
        for j in range(n - 1):
            t = np.zeros(num_cells, dtype=int)
            t[i * n + j] = 1
            t[(i + 1) * n + j] = 1
            t[(i + 1) * n + (j + 1)] = 1
            trominoes.append(t)
    rows = []
    for i in range(n):
        r = np.zeros(num_cells, dtype=int)
        for j in range(n):
            r[i * n + j] = 1
        rows.append(r)
    cols = []
    for j in range(n):
        c = np.zeros(num_cells, dtype=int)
        for i in range(n):
            c[i * n + j] = 1
        cols.append(c)

    matrix = []
    for t in trominoes: matrix.append(t)
    for r in rows: matrix.append(r)
    for c in cols: matrix.append(c)
    matrix = np.array(matrix)
    r = rank_gf2(matrix)
    return r < ((n-1)**2 + 2*n - 1)

